const base = (id, area, game, kind, d, q, exp, src, more = {}) => ({ id, area, game, kind, d, q, exp, src: Array.isArray(src) ? src : [src], checked: CK, by: BY, ver: 1, status: "checked", assets: [], tags: KR_IDS.has(id) || /^H\d{4}$/.test(id) ? ["한국사"] : [], ...more });
const mcq = (id, area, game, d, q, opts, exp, src, more) => base(id, area, game, "mcq", d, q, exp, src, { opts, ...more });
const ox = (id, area, game, d, q, ans, exp, src, more) => base(id, area, game, "ox", d, q, exp, src, { ans, ...more });
const order = (id, area, game, d, q, events, exp, src, more) => base(id, area, game, "order", d, q, exp, src, { events, ...more });
const num = (id, area, game, d, q, n, exp, src, more) => base(id, area, game, "num", d, q, exp, src, { n, ...more });
const map = (id, area, d, q, codes, exp, src, more) => base(id, area, "world", "map", d, q, exp, src, { codes, ...more });
const pair = (id, area, game, d, q, pairs, exp, src, more) => base(id, area, game, "pair", d, q, exp, src, { pairs, ...more });
const reveal = (id, area, d, q, clues, opts, exp, src, more) => base(id, area, "reveal", "reveal", d, q, exp, src, { clues, opts, ...more });
const fake = (id, area, d, q, stmts, exp, src, more) => base(id, area, "fake", "fake", d, q, exp, src, { stmts, ...more });

